const existing = db.prepare("SELECT count(*) AS count FROM polls").get() as { count: number };
if (existing.count === 0) {
  const seed = JSON.parse(readFileSync(new URL("../fixtures/catalog.json", import.meta.url), "utf8")) as CatalogSeed;
  db.exec("BEGIN");
